/** Every event this service sends to EventBridge, keyed by its `detail-type`. */
export interface Events {
  "Advisor Recommendation Status Open": AdvisorRecommendationStatusOpenEvent;
  "Advisor Recommendation Status Resolved": AdvisorRecommendationStatusResolvedEvent;
  "AWS API Call via CloudTrail": AWSAPICallviaCloudTrailEvent;
  "AWS Console Action via CloudTrail": AWSConsoleActionviaCloudTrailEvent;
  "AWS Console Sign In via CloudTrail": AWSConsoleSignInviaCloudTrailEvent;
  "AWS Insight via CloudTrail": AWSInsightviaCloudTrailEvent;
  "AWS Mcp Event via CloudTrail": AWSMcpEventviaCloudTrailEvent;
  "AWS Network Activity Event via CloudTrail": AWSNetworkActivityEventviaCloudTrailEvent;
  "AWS Service Event via CloudTrail": AWSServiceEventviaCloudTrailEvent;
  "Email Bounced": EmailBouncedEvent;
  "Email Clicked": EmailClickedEvent;
  "Email Complaint Received": EmailComplaintReceivedEvent;
  "Email Delivered": EmailDeliveredEvent;
  "Email Delivery Delayed": EmailDeliveryDelayedEvent;
  "Email Opened": EmailOpenedEvent;
  "Email Rejected": EmailRejectedEvent;
  "Email Rendering Failed": EmailRenderingFailedEvent;
  "Email Sent": EmailSentEvent;
  "Email Subscribed": EmailSubscribedEvent;
  "Sending Status Disabled": SendingStatusDisabledEvent;
  "Sending Status Enabled": SendingStatusEnabledEvent;
}

/** An event's `detail-type`. */
export type DetailType = keyof Events;

/** Any event this service sends, narrowed by its `detail-type`. */
export type Event = { [K in DetailType]: Events[K] & { "detail-type": K } }[DetailType];
